"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9068],{6420:e=>{e.exports=JSON.parse('{"functions":[{"name":"init","desc":"Bootstrap hook. Requires every child of the sibling `Watchers` folder,\\nwhich is what registers each watcher\'s handler.","params":[],"returns":[],"function_type":"static","source":{"line":44,"path":"src/Client/Features/CollectionWatcher/CollectionWatcherController.luau"}}],"properties":[],"types":[],"name":"CollectionWatcherController","desc":"Activates every tag-driven behavior in the `Watchers` folder.\\n\\nThe pattern: a lot of world objects need client behavior that has nothing\\nto do with React and shouldn\'t need a controller each \u2014 a button that\\nscales on hover, a pad that teleports you. Instead of wiring those up\\nindividually, each behavior is a module under `Watchers/` that builds a\\n[CollectionWatcher] for one CollectionService tag and registers a handler.\\nThe handler runs once per tagged instance, for instances that already\\nexist and for any added later, and the [CollectionObject] wrapper gives it\\na `Destroyed` signal for teardown.\\n\\nAdding a behavior is therefore: drop a module in `Watchers/`, tag the\\ninstances in Studio. Nothing here changes, and nothing has to import the\\nnew module \u2014 [CollectionWatcherController.init] requires whatever it finds.\\n\\nCurrent watchers:\\n\\n* `Watchers/ScalingButton` \u2014 tag `ScalingButton`, hover/press scale tweens\\n* `Watchers/TeleportPad` \u2014 tag `TeleportPad`, touch-to-teleport\\n\\n:::note\\nModules are required for their side effects \u2014 the returned watcher is\\ndiscarded. A watcher module must therefore do its `RegisterHandler` call\\nat require time, not export a setup function.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","realm":["Client"],"source":{"line":34,"path":"src/Client/Features/CollectionWatcher/CollectionWatcherController.luau"}}')}}]);